# -*- coding: utf-8 -*-
import json, subprocess
res=json.load(open(r'C:/Users/Administrator/.dsh/cache/memory-audit/result.json',encoding='utf-8'))
def ov_read(uri):
    p=subprocess.run(['ov','read',uri],capture_output=True,text=True,encoding='utf-8',errors='replace',timeout=60)
    return p.stdout or ''
def status(txt):
    for ln in txt.splitlines()[:12]:
        if ln.startswith('audit_status:'):
            return ln.split(':',1)[1].strip()
    return None
bad=[]
ok=0
for r in res:
    uri=r['uri']; want=r['verdict']
    try:
        txt=ov_read(uri); got=status(txt)
    except Exception as e:
        got='ERR:'+str(e)[:40]
    if got==want: ok+=1
    else: bad.append((uri.split('/')[-1],want,got))
print('verified-ok',ok,'/',len(res))
for b in bad: print(' MISMATCH',b)

